  "AI-created question evaluation": "AI 原創題目測試結果",
  "Strict session: no hints. This AI-created question was cross-checked on sampled inputs, not proven correct. Evaluation cases appear after finishing.": "嚴格面試不提供提示。這道 AI 原創題目已用抽樣輸入交叉檢查，但尚未證明正確；結束後才顯示評估案例。",
  "Coaching session: requested hints are recorded. This AI-created question was cross-checked on sampled inputs, not proven correct. Evaluation cases appear after finishing.": "引導面試會記錄提示使用情形。這道 AI 原創題目已用抽樣輸入交叉檢查，但尚未證明正確；結束後才顯示評估案例。",
  "AI-generated evaluation cases derived from cross-checked solutions. Agreement on sampled inputs does not prove that the problem or expectations are correct.": "評估案例的預期值來自經交叉檢查的 AI 解法；抽樣結果一致不代表題目或預期值必然正確。",
  "The new question did not show enough varied outcomes. No question was saved.": "新題在檢查中沒有足夠多樣的輸出，這道題目沒有儲存。",
