  "The new question could not produce enough distinct checks. No question was saved.": "新題無法建立足夠的不同測試，這道題目沒有儲存。",
  "A generated solution exceeded the output limit. No question was saved.": "生成解法的輸出超過限制，這道題目沒有儲存。",
