  "Anything you want to explore? (optional)": "想特別練什麼？（選填）",
  "For example: BFS with more than one destination": "例如：有多個目的地的 BFS 題目",
  "Creates a new contract, two solution implementations and tests. A question is saved only when the implementations agree on application-generated inputs. One AI request per click; no automatic retries.": "產生新的題目規格、兩種解法與測試，兩種解法在系統產生的輸入上結果一致才會儲存。每次點擊使用一次 AI 請求，不會自動重試。",
  "First release: bounded integers, short arrays and strings, and small matrices. New questions currently support coding practice; bug repair and optimization use the curated collection.": "第一版支援有界整數、短陣列、短字串與小矩陣。全新題目目前支援撰寫解法；修復錯誤與效能練習使用精選題庫。",
  "New AI-created question": "AI 原創題目 · 已交叉檢查",
  "Two implementations agreed on {0} checked inputs.": "兩種解法在 {0} 個輸入上的執行結果一致。",
  "Both solutions were generated by AI. Agreement is a consistency check, not proof that the problem or expected answers are correct. Difficulty is an AI estimate.": "兩種解法皆由 AI 產生；結果一致僅屬一致性檢查，不代表題意或預期答案必然正確。難度為 AI 估計。",
  "The two generated solutions disagree. No question was saved.": "兩種生成解法的執行結果不同，這道題目沒有儲存。",
