  "Recorded hidden-test submissions count as practice. Repeating the same question on the same day counts once. New and revisited are based on the first saved submission for each question contract. Creating questions and running public examples do not count.": "提交隱藏測試才計入練習，同一道題目在同一天只算一次。以各題目規格最早保留的提交紀錄，區分新練與複習；僅產生題目或執行公開範例不計入。",
  "These totals use saved practice results; older attempts may no longer be retained. Passing describes tested cases, not mastery. Daily goals are saved in this browser.": "統計依據目前儲存的練習結果，較早的嘗試可能已不再保留。通過代表測試案例通過，不等同完全掌握。每日目標儲存在這個瀏覽器。",
