  "4. AI reflection · Not verified": "4. AI 反思建議 · 尚未驗證",
  "3 < 5 → positions 0 and 1 are impossible.": "3 < 5 → 位置 0 和 1 不可能是答案。",
  "500 > 500 is false, so this function reaches the return-60 branch.": "500 > 500 不成立，因此函式走到回傳 60 的分支。",
  "A filled boundary includes equality; an open one excludes it.": "實心端點包含等於的情況；空心端點不包含。",
  "A limited Python AST check of dynamic execution, pickle deserialization, and shell calls. Warnings need review; they are separate from test failures and do not confirm an exploit. No warnings does not mean the code is secure.": "以 Python AST 檢查動態執行、pickle 反序列化及 shell 呼叫。警告需要人工檢視，與測試失敗分開呈現，也不代表漏洞已被利用。沒有警告不表示程式一定安全。",
  "A little clarity, every iteration.": "每次改進，都更清楚一點。",
  "A mathematical formula is not the whole contract": "數學公式並不等於完整需求",
  "A midpoint is an index, so a fraction must become a valid integer.": "中點是索引，因此必須把小數轉成有效整數。",
  "A palindrome check should ignore case and spaces. Does it?": "迴文檢查應忽略大小寫與空格。這段程式做到了嗎？",
  "A piecewise rule chooses one of two outcomes": "分段規則決定兩種結果中的一種",
  "A repair is a hypothesis until the unchanged cases run.": "在原有案例重新執行前，修正仍只是假設。",
  "A saved input/expectation is absent from this run. Review the current tests; no evidence is transferred to an edited expected value.": "這次執行缺少先前的輸入與預期組合。請檢查目前測試；改過預期值的案例不會沿用舊證據。",
  "A scan checks candidates one by one.": "線性掃描會逐一檢查候選位置。",
  "A smaller failure, reproduced": "已重現更小的失敗案例",
  "A successful normal case can hide an invalid operation.": "一般案例成功，仍可能藏著無效運算。",
  "A three-point boundary check can expose a one-symbol error.": "邊界前、邊界上、邊界後，三個測試就能揭露一個符號的錯誤。",
  "A valid execution can still violate the requirement.": "程式能正常執行，仍可能違反需求。",
