  "Authored worked explanations are labeled separately from recorded Python events. Playback follows narration, not measured runtime. Kokoro generates speech on this computer and reuses saved audio, with no API fee. Browser voices and captions remain available as alternatives. Finished interviews can open their evaluation traces here.": "教學示意與實際 Python 執行紀錄會分別標示。播放依旁白推進，不代表實際執行速度。Kokoro 在這台電腦產生語音並重用已儲存音訊，不收 API 費用。也可選擇瀏覽器語音或字幕。已結束的面試可在這裡回放評估紀錄。",
  "Average the two indices, not the array values.": "取平均的是兩個索引，不是陣列中的數值。",
