  "Choose a test and predict the implementation’s return value as JSON, e.g. true, 0, or \"hello\". Normal verification also works without a prediction.": "選擇測試，以 JSON 預測程式實際會回傳的值，例如 true、0 或 \"hello\"。也可以不預測，直接驗證。",
