  "Explain your reasoning, write tests, repair Python code, and answer follow-up questions. Choose an interviewer before starting; the mode is fixed for that session.": "說明推理、撰寫測試、修正 Python 程式，並回答追問。開始前先選擇考官，這場面試的模式將固定。",
