  "Final curated evaluation": "最終精選案例評估",
  "Final feedback is a simulated interviewer's interpretation of recorded answers and limited execution evidence. It is not a hiring verdict or proof of interview readiness. Starting or reopening another session replaces this interview editor; your verification workspace is separate.": "最終回饋是模擬考官根據回答與有限執行證據所做的解讀，不是錄取判定，也不能證明面試準備已完成。開啟其他面試會取代此編輯器內容；驗證工作區則獨立保留。",
  "Find a smaller failing input": "找出更小的失敗輸入",
