  "Find the first even number. What if it is the last item?": "找出第一個偶數。如果它在最後一個位置呢？",
  "Find the first matching index. Can the loop skip the final candidate or return a later duplicate?": "找出第一個相符索引。迴圈會漏掉最後候選位置，或回傳後面的重複值嗎？",
  "Find the target without checking every number": "不用逐一檢查，也能找到目標",
