  "Fix the existing cases JSON first, or start a blank task.": "請先修正現有案例的 JSON，或開始空白任務。",
  "Floor means the greatest integer no larger than the fraction.": "向下取整是取不大於原數值的最大整數。",
  "For n > 0: O(log n) time, O(1) auxiliary space.": "當 n > 0：時間 O(log n)，額外空間 O(1)。",
