  "Generating a plan sends the intent, code, and existing cases to your configured model and uses API credits. Candidates are proposals, not execution evidence.": "產生計畫會將需求、程式碼與現有案例傳送至設定的模型，並使用 API 額度。候選案例是提案，並非執行證據。",
