  "Line events show variable state before the highlighted line executes. Traces cover main-thread Python function frames; values and event counts are limited.": "行事件顯示反白行執行前的變數狀態。紀錄僅涵蓋主執行緒的 Python 函式，變數內容與事件數量皆有上限。",
