  "Loading saved runs…": "正在載入執行紀錄…",
  "Local Docker environment": "本機 Docker 環境",
  "Local Docker is selected. No cloud usage is started by opening history.": "已選擇本機 Docker。開啟歷史紀錄不會啟動雲端執行。",
  "Local Docker only, regardless of the next-run environment selector. At most 10 case executions including replays, up to 4 search rounds. No Meta or Modal credits. Original code and tests stay unchanged.": "僅使用本機 Docker，不受下一次執行環境選擇影響。包含重播最多執行 10 個案例，最多搜尋 4 輪。不使用 Meta 或 Modal 額度，原始程式與測試保持不變。",
  "Local Docker only. At most one original replay and three variant runs, using the same supplied cases. A variant still passing may indicate missing tests, unreachable code, or equivalent behavior. Execution errors and timeouts are reported separately. No Meta or Modal credits.": "僅使用本機 Docker，最多重播原版一次、執行變異版三次，皆使用相同案例。變異版仍通過可能是測試不足、程式無法到達或行為等價。錯誤與逾時分開呈現，不使用 Meta 或 Modal 額度。",
  "Local Docker selected: execution stays on this computer. Viewing history or reports does not start a cloud job.": "已選擇本機 Docker：程式留在此電腦執行。查看紀錄或報告不會啟動雲端工作。",
  "Local Docker · This computer": "本機 Docker · 此電腦",
