  "Modal cloud configuration": "Modal 雲端設定",
  "Modal selected: the submitted code and tests go to Modal. A new CPU Sandbox uses Modal credits; outbound network is blocked and lifetime is capped at 30s after startup. Cold starts can take longer. No automatic Docker fallback.": "已選擇 Modal：程式與測試會傳送至 Modal。新的 CPU 沙箱會使用 Modal 額度，禁止對外連線，啟動後最多存活 30 秒。冷啟動可能較久，不會自動改用 Docker。",
  "Modal · Cloud CPU · Uses Modal credits": "Modal · 雲端 CPU · 使用 Modal 額度",
  "Mode for a new interview": "新面試的考官模式",
  "Model request in progress…": "模型請求處理中…",
  "Move left past the tested midpoint.": "將 left 移到已檢查中點的下一個位置。",
  "Moving sweets changes who has them, not how many exist.": "移動糖果只改變誰拿到它們，不改變總數。",
  "My predicted return value · JSON": "我預測的回傳值 · JSON",
  "NO ASSUMPTIONS. JUST EVIDENCE.": "用證據說話，不靠猜測。",
