  "Natural-language intent is not automatically proven. Untested inputs, security vulnerabilities, external integrations, and concurrent behavior have not been checked. A captured exception may be handled by the program; the final case outcome determines pass/fail.": "自然語言需求不會自動獲得證明。未測試的輸入、安全漏洞、外部整合與並行行為尚未檢查。程式可能會處理記錄到的例外；是否通過以案例最終結果為準。",
  "Need a hint? Open mentor": "需要提示嗎？開啟導師",
