  "No captured function trace is selected. A syntax/module error can have an observed result without a replayable function path.": "尚未選取函式執行紀錄。語法或模組錯誤可能有結果，但沒有可回放的函式路徑。",
  "No code changes between these runs.": "這兩次執行之間沒有程式碼變更。",
