  "No function events were captured. Syntax errors, module initialization errors, disabled tracing, or capture limits may leave no trace. The error/result above remains the observed outcome.": "未記錄到函式事件。語法或模組初始化錯誤、關閉追蹤、超出記錄上限都可能造成沒有軌跡。上方錯誤或結果仍是實際觀察到的輸出。",
  "No local variables captured at this step.": "此步驟未記錄到區域變數。",
  "No locals captured at this event.": "此事件未記錄到區域變數。",
  "No network · Resource limits · Isolated runs": "禁止連網 · 資源限制 · 隔離執行",
  "No new distinct candidates are available in this plan. This does not establish completeness or correctness.": "此計畫沒有新的不重複候選案例。這不能證明測試完整或程式正確。",
  "No new distinct cases were proposed. This is not proof of correctness.": "沒有提出新的不重複案例。這不代表程式一定正確。",
  "No personal practice recorded yet. Before your next prediction, select “Include this next run in my personal practice log.” Demonstrations stay separate.": "尚無個人練習紀錄。下次預測前，請勾選「將下一次執行列入個人練習紀錄」。示範紀錄會分開保留。",
  "No positions to inspect": "沒有可檢查的位置",
