  "One optional model request, up to six proposals, 2,048 completion tokens plus prompt tokens. Saved maps are reused. Generation, review, and reopening execute no code. Suggested links start unchecked; this map is not code coverage or proof of completeness.": "可選擇發出一次模型請求，最多六項提案，回覆上限 2,048 tokens，另計提示 tokens。重用已儲存對應表。產生、確認與重新開啟皆不執行程式。建議連結預設不勾選；此表不是程式碼覆蓋率，也不是完整性證明。",
  "Open Docker Desktop with Linux containers, run": "請開啟 Docker Desktop 並使用 Linux 容器，執行",
  "Open quick start guide": "開啟快速入門指南",
  "Open saved run": "開啟執行紀錄",
  "Optional: sends this run’s code, selected test, observed result, prediction and explanation to {0}. Uses API credits when clicked. Identical saved feedback is reused.": "選用功能：將程式碼、選取測試、實際結果、預測與說明傳送至 {0}。點擊時會使用 API 額度，相同回饋會重用。",
  "Order total → delivery fee": "訂單金額 → 運費",
  "Ordinary inputs work. But what should an empty list return?": "一般輸入可以運作，那空串列應該回傳什麼？",
