  "Passed": "通過",
  "Passing tests confirms only the supplied cases, not correctness for every possible input.": "測試通過只確認提供的案例，不能保證所有可能輸入都正確。",
  "Passing your current tests is a starting point. Ask the configured model to propose up to three different, intent-backed cases for the last completed passing run. Review their expectations before running them.": "通過目前測試只是起點。可請模型針對最近一次全部通過的執行，依需求提出最多三個不同案例。執行前請先確認預期值。",
