  "Practice examples": "練習範例",
  "Practice loaded. Make your own prediction before running; no AI call was made.": "練習已載入。執行前先做出自己的預測；尚未呼叫 AI。",
  "Practice mentor · Prewritten, no AI call: At exactly $500, is “greater than 500” true? Which comparison includes the boundary promised by “500 or more”?": "內建練習引導，未呼叫 AI：剛好 $500 時，「大於 500」成立嗎？哪種比較能包含「500 以上」承諾的邊界？",
  "Predict the boundary case": "預測邊界案例",
  "Predict the original code, not the intended rule.": "預測原始程式的結果，而不是需求規則的結果。",
  "Predict what the current implementation will return, then compare it with Python's output and the test expectation. Your prediction never changes pass/fail. Existing results and expectations may already be visible; this is practice, not a skill score.": "預測目前程式會回傳什麼，再與 Python 輸出及測試預期值比較。預測不影響通過與否。你可能已經看得到結果與預期值，因此這是練習，不是能力評分。",
  "Predict → Explain → Reflect": "預測 → 解釋 → 反思",
