  "Results apply only to the supplied cases. Model-proposed expected values require user confirmation. Curated challenges are human-authored. Changed expectations are not fixes. AI suggestions have not been verified. Predictions are learning responses, never test expectations or proof of independent skill.": "結果只適用於提供的案例。模型提出的預期值需由使用者確認，精選挑戰由人工撰寫。改變預期值不算修好程式。AI 建議尚未驗證；預測是學習回答，不是測試預期值，也不能證明獨立解題能力。",
