  "Review the curated expectations, predict the code’s behavior, then explain what you observed. Repeated exposure and visible expectations mean this is practice, not a blinded assessment.": "確認精選預期值，預測程式行為，再解釋觀察結果。因為可以看到預期值並重複練習，這不是盲測能力評量。",
