  "{0}/{1} questions answered · {2}/{3} hints used · {4} known reported tokens (missing usage is excluded)": "已回答 {0} / {1} 題 · 使用提示 {2} / {3} · 已知用量 {4} tokens（不含缺漏用量）",
  "{0}/{1} supplied cases passed · {2}{3}": "提供的案例通過 {0} / {1} · {2}{3}",
  "{0}/{1} supplied cases passed. Explore different inputs; existing expectations stay unchanged.": "提供的案例通過 {0} / {1}。試試不同輸入，現有預期值保持不變。",
  "{0}/{1} · {2} · line {3} · {4}": "{0} / {1} · {2} · 第 {3} 行 · {4}",
  "“At least” includes the threshold itself.": "「至少」包含門檻本身。",
  "← Previous": "← 上一步",
  "← Previous chapter": "← 上一章",
  "← Previous idea": "← 上一個觀念",
  "⌊z⌋ means floor; Python uses // here.": "⌊z⌋ 代表向下取整；Python 在此使用 //。",
  "✓ Passed": "✓ 通過",
  "✕ Mismatch": "✕ 結果不符",
  "✕ Wrong output": "✕ 輸出錯誤",
  "＋ Add argument": "＋ 新增引數",
  "＋ Add case": "＋ 新增案例",
  "Page language": "頁面語言",
  "Voice settings": "語音設定",
  "The non-negative order total.": "非負的訂單總金額。",
  "The inclusive free-delivery threshold.": "包含等於情況的免運門檻。",
  "Greater than OR equal to; the boundary is included.": "大於或等於，包含邊界本身。",
  "fee(x) = 0 if x ≥ 500; otherwise 60": "fee(x) = 0（x ≥ 500）；否則為 60",
  "x = 499: 499 ≥ 500 is false, so the fee is 60.": "x = 499：499 ≥ 500 不成立，所以運費為 60。",
  "x = 500: 500 ≥ 500 is true, so the fee must be 0.": "x = 500：500 ≥ 500 成立，所以運費必須為 0。",
  "x = 501: 501 ≥ 500 is true, so the fee is 0.": "x = 501：501 ≥ 500 成立，所以運費為 0。",
  "mean = (Σ xᵢ) / n, for n > 0": "平均值 = (Σ xᵢ) / n，適用於 n > 0",
  "The number of values in the list.": "串列中的資料數量。",
  "The value at position i (mathematical numbering starts at 1 here).": "第 i 個位置的值（這裡的數學編號從 1 開始）。",
  "Sigma means add every value; Σ xᵢ is the total.": "Sigma 表示把每個值相加；Σ xᵢ 就是總和。",
  "For [2, 4, 6], n = 3 and Σ xᵢ = 2 + 4 + 6 = 12.": "對 [2，4，6]，n = 3，Σ xᵢ = 2 + 4 + 6 = 12。",
  "mean = 12 / 3 = 4. For [-4, 2], mean = -2 / 2 = -1.": "平均值 = 12 / 3 = 4。對 [-4，2]，平均值 = -2 / 2 = -1。",
  "For [], n = 0. The expression 0 / 0 is undefined.": "對 []，n = 0。算式 0 / 0 在數學上沒有定義。",
  "Returning 0 for [] is this application’s explicit rule, not a general mathematical definition of an empty mean.": "[] 回傳 0 是這個應用明訂的規則，不是空串列平均值的一般數學定義。",
  "Inclusive indices delimiting the remaining candidates.": "剩餘候選範圍的左右索引，包含兩端點本身。",
  "Floor: the greatest integer less than or equal to z.": "向下取整：小於或等於 z 的最大整數。",
  "Python floor division. Valid array indices here are non-negative.": "Python 向下取整除法。此處有效陣列索引為非負整數。",
  "For indices 0 through 2, mid = floor((0 + 2) / 2) = 1.": "索引範圍 0 到 2：mid = floor((0 + 2) / 2) = 1。",
  "nums[1] is 3. Target 5 is larger, so left becomes 2.": "nums[1] 是 3。目標 5 比它大，所以 left 變為 2。",
  "Now left = right = 2. There is still one candidate: nums[2] = 5.": "此時 left = right = 2，仍有一個候選：nums[2] = 5。",
  "left < right is false, so the buggy loop stops before checking it.": "left < right 不成立，因此錯誤迴圈還沒檢查它就停止。",
  "With an inclusive range, continue while left ≤ right. Empty input starts at left = 0, right = -1, so there is no candidate.": "範圍包含端點時，left ≤ right 就應繼續。空輸入初始為 left = 0、right = -1，因此沒有候選。",
