  "When the result differs from your expectation,\nwhich assumption would you check first?": "當結果不符合你的預期，\n你會先檢查哪個假設？",
  "Compare the failing cases with the passing ones.\nCould an unhandled edge case explain the difference?": "比較失敗與通過的案例。\n差異是否來自尚未處理的邊界情況？",
  "Try the smallest fix, then rerun the same cases.\nAdd another case that would catch the same bug.": "嘗試最小修正，再跑相同案例。\n新增另一個能抓到相同錯誤的案例。",
  "Code or tests changed · Run again": "程式或測試已修改 · 請重跑",
