  "The test suite changed": "測試集已變更",
  "This is not a comparison of the same tests. Changed expectations cannot establish a repair. Inspect the comparison below.": "這不是相同測試的比較。改變預期值不能證明修好程式，請查看下方對照。",
  "Repair verified on the same tests": "已用相同測試確認修正",
