  "These results cover only the supplied inputs. Export the evidence or add another boundary case.": "結果僅涵蓋提供的輸入。可匯出證據，或新增其他邊界案例。",
  "Next: edit your code, then rerun": "下一步：修改程式，再次執行",
  "Use Pin baseline below to save this run for comparison.": "使用下方「固定比較基準」，儲存這次執行以便比較。",
  "A completed run is saved as the comparison baseline.": "已將完成的執行儲存為比較基準。",
  "Keep the intent and test expectations unchanged while you repair the code.": "修正程式時，請保留需求與測試預期值。",
  "New cases exposed an untested failure": "新案例揭露了先前未測到的失敗",
  "The added cases passed too": "新增的案例也通過了",
  "Keep the original expectations": "保留原始預期值",
  "The function, intent, or test cases changed. Restart this demo to compare the same three checks.": "函式、需求或案例已修改。請重啟示範，才能比較相同三項測試。",
  "The reviewed examples expect 60 at $499, 0 at $500, and 0 at $501. Run Python to see what this implementation returns.": "確認過的範例預期：$499 回傳 60，$500 與 $501 回傳 0。請執行 Python 查看實際結果。",
  "Inspect the observed results below, then reveal a question to guide your fix.": "先查看下方結果，再開啟引導修正的提問。",
  "Edit the condition in Your code below. Keep the intent and all three expected values unchanged.": "在下方「你的程式碼」修改條件，保留需求與三個預期值。",
  "Run the same three cases again. Editing code alone does not prove the bug is fixed.": "請重跑相同三個案例。只修改程式，還不能證明錯誤已修好。",
  "Repair verified on the same 3 tests": "已用相同 3 個測試確認修正",
  "Clarify before testing": "測試前先釐清",
  "Assumptions to review": "待確認的假設",
  "Hypotheses · not confirmed findings": "假設 · 尚未確認的發現",
