  "Selected cases passed · broader behavior remains unverified": "選取案例通過 · 更廣泛行為尚未驗證",
  "Not checked · no confirmed linked cases executed": "未檢查 · 尚未執行已確認的對應案例",
  "Fill in Intended Behavior, your Python code, and the target function first.": "請先填入預期行為、Python 程式碼與目標函式。",
  "Test cases must be an array. Use [] for no existing cases.": "測試案例必須是陣列。沒有現有案例時請使用 []。",
  "Confirm the assumptions and selected expected values first.": "請先確認假設與選取的預期值。",
  "Select at least one case whose expected value you have reviewed.": "請至少選取一個已確認預期值的案例。",
  "The editor changed during confirmation. Regenerate and review the plan for the new input.": "確認期間輸入已修改。請為新輸入重新產生並確認計畫。",
  "Invalid arguments": "引數無效",
  "EXPECTED RETURN VALUE": "預期回傳值",
  "Missing expected value": "缺少預期值",
  "Fix the JSON array in Advanced first.": "請先修正進階區域的 JSON 陣列。",
  "Fix this case in Advanced first.": "請先在進階區域修正此案例。",
  "Curated challenges require an unchanged practice-example intent and matching function. Load an example, or author your own cases for custom behavior.": "精選挑戰需要原始練習需求與相符函式。請載入範例，或為自訂行為撰寫自己的案例。",
  "No trace metadata was returned for this run.": "此次執行沒有回傳軌跡資訊。",
  "Before this line executes": "這一行執行前",
