  "Function entered": "進入函式",
  "New case": "新增案例",
  "Connection lost or timed out. Check that the local server is running, then check the environment again.": "連線中斷或逾時。請確認本機伺服器正在執行，再重新檢查環境。",
  "Unable to read the server response. Refresh the page.": "無法讀取伺服器回覆，請重新整理頁面。",
  "Request failed. Please try again.": "請求失敗，請重試。",
  "Wrong output": "輸出錯誤",
  "Execution errors": "執行錯誤",
  "AI-proposed test · Expected value confirmed by you": "AI 提出的測試 · 預期值已由你確認",
  "Curated example · Expected value follows the confirmed contract": "精選範例 · 預期值依據已確認契約",
  "Supplied test · Checked against your expected value": "提供的測試 · 與你的預期值比較",
  "Modal cloud CPU": "Modal 雲端 CPU",
  "Local Docker": "本機 Docker",
  "Execution environment not recorded": "未記錄執行環境",
  "The guarded contract or test suite changed. Restore the saved values, or release Regression Guard to run editable tests.": "受保護的契約或測試集已修改。請恢復已儲存值，或解除回歸保護來執行可編輯測試。",
  "Enter your Python code first.": "請先輸入 Python 程式碼。",
  "Enter a valid Python function name.": "請輸入有效 Python 函式名稱。",
  "Provide between 1 and 20 JSON test cases.": "請提供 1 到 20 個 JSON 測試案例。",
  "Each case must include an args array and an expected value.": "每個案例都需要 args 陣列與 expected 預期值。",
  "Test cases must be an array.": "測試案例必須是陣列。",
  "Enter a valid expected value. Text must be in double quotes.": "請輸入有效預期值，文字必須加上雙引號。",
  "The limit is 20 cases.": "案例上限為 20 個。",
  "The voice returned an invalid audio URL.": "語音服務回傳了無效音訊網址。",
