  "Not recorded": "未記錄",
  "Supplied expectation matched": "符合提供的預期值",
  "Return-value mismatch observed": "觀察到回傳值不符",
  "Execution error observed": "觀察到執行錯誤",
  "Choose an existing completed test.": "請選擇已完成的測試。",
  "No captured function events are available for this test. No execution path can be replayed.": "此測試沒有函式事件紀錄，無法回放執行路徑。",
  "Captured variable previews are bounded. Events describe recorded execution only.": "變數預覽內容有限。事件只描述已記錄的執行。",
  "Replay pacing is instructional, not measured execution timing.": "回放速度用於教學，不代表實際執行時間。",
  "Compare the supplied expectation with the recorded outcome. Before stepping, predict what this implementation will do for this exact input.": "對照預期值與實際結果。往下看之前，先預測目前程式對這個輸入會做什麼。",
  "This snapshot is BEFORE the highlighted line executes. Read the captured locals, predict the next step, then compare with the next recorded event.": "這是反白行執行前的快照。查看區域變數，預測下一步，再與下一筆事件比較。",
  "Python captured a function call. Identify the input previews and connect them to the supplied test before moving forward.": "Python 記錄到函式呼叫。先辨認輸入預覽與提供的測試之間的關係，再往下看。",
  "An exception": "一個例外",
  "This input matched its supplied expectation. Ask which other inputs remain untested; one passing example does not prove correctness.": "此輸入符合提供的預期值。想想還有哪些輸入沒測過；單一通過案例不能證明程式正確。",
  "Use this exact input to reproduce the observation. Explain one hypothesis, make one deliberate repair, and rerun unchanged expectations. This replay does not apply or verify a repair.": "用相同輸入重現結果。提出一個假設，做一次有依據的修正，再跑原有預期值。此回放本身不會套用或驗證修正。",
  "Choose a video frame budget from 3 to 30.": "請選擇 3 到 30 個影片畫面。",
  "None": "零個",
  "Exactly one": "剛好一個",
  "Line events show state before the line executes. Variable previews are bounded; custom objects are not expanded. Main-thread Python function frames only.": "行事件顯示該行執行前的狀態。變數預覽有限，自訂物件不展開，僅涵蓋主執行緒的 Python 函式。",
  "Before line {0} executes": "第 {0} 行執行前",
  "Enter {0}": "進入 {0}",
  "Exception captured at line {0}": "第 {0} 行記錄到例外",
  "Return / unwind event at line {0}": "第 {0} 行回傳／離開函式",
  "1. Read the contract and reproduce the input": "1. 閱讀契約並重現輸入",
  "{0} Keep the intent and test expectations unchanged while you repair the code.": "{0} 修正程式時，請保留需求與測試預期值。",
  "Debug a threshold counter": "除錯：門檻計數器",
  "Debug a reservation rule": "除錯：訂位規則",
  "Debug a first-match search": "除錯：第一個相符位置",
  "Talk me through your initial approach. What would you inspect or test first, and why?": "請說明你的初步思路。你會先檢查或測試什麼？為什麼？",
  "Walk through the current implementation on an input you choose. What do you predict it will return?": "自行選一個輸入，逐步走過目前程式。你預測它會回傳什麼？",
  "Which tests would you design for this contract, and why are those tests useful?": "你會為這份契約設計哪些測試？為什麼這些測試有用？",
  "What do you think causes the discrepancy, and what observation supports that explanation?": "你認為差異的原因是什麼？有哪些觀察支持這個解釋？",
  "Explain why each change in your proposed repair is necessary.": "請說明修正方案中的每一項變更為什麼必要。",
  "What are the time and auxiliary space complexities of your approach? Explain your assumptions.": "你的解法時間與額外空間複雜度是多少？請說明假設。",
  "How would you check that your repair preserves the required behavior?": "你會如何檢查修正後仍保留需求要求的行為？",
  "Choose a small input and walk through which positions the loop visits.": "選一個小輸入，逐步確認迴圈會走訪哪些位置。",
  "Pick a boundary directly from the stated booking rule.": "直接從訂位需求中挑出一個邊界情況。",
  "Trace the indices visited by a very short list.": "用很短的串列，追蹤實際走訪的索引。",
  "No hints during this session. Follow-up questions come from a reviewed neutral question bank. You may run your own tests. Curated evaluation cases and optional AI feedback are available only after finishing. This local tool does not prevent access to other tools.": "此場面試不提供提示。追問來自已檢視的中立題庫。你可以執行自己的測試；精選評估案例與選用 AI 回饋會在結束後提供。此本機工具不會阻止你使用其他工具。",
  "Coaching session. Hint 1 is a free direction prompt; hints 2 and 3 use the model. Hints are recorded; follow-up questions come from a reviewed neutral question bank. Curated evaluation cases are revealed after finishing.": "引導面試：提示 1 是免費方向引導，提示 2、3 使用模型。提示次數會記錄；追問來自已檢視的中立題庫。精選評估案例在結束後揭曉。",
  "New context: reserving the final seat": "新情境：預訂最後一個座位",
  "New context: checking every measurement": "新情境：檢查每筆測量值",
  "Inclusive boundaries": "包含端點的邊界",
  "Loop coverage": "迴圈涵蓋範圍",
  "Self-selected personal practice only. Demonstration, unclassified, and non-prediction runs are excluded. Matches describe observed execution, not code correctness or skill mastery. Review covers the latest 100 saved runs.": "只計入自行選擇的個人練習，排除示範、未分類與未預測的執行。預測符合結果只描述實際觀察，不代表程式正確或已掌握技能。檢視範圍為最近 100 筆紀錄。",
  "Sum all integers; empty list returns 0.": "所有整數加總；空串列回傳 0。",
  "Arithmetic mean of all integers; empty list returns 0.": "所有整數的算術平均值；空串列回傳 0。",
  "Return true if any integer is positive; empty list returns false.": "任一整數為正就回傳 true；空串列回傳 false。",
  "Return the first even integer, or null if none exists.": "回傳第一個偶數；沒有則回傳 null。",
  "OA review practice counts as revisiting a previously seen question. Original OA grading is shown separately below.": "OA 考後重練會計為複習已看過的題目。原始 OA 成績會在下方分開顯示。",
