  "Up to 10 case executions. Deletion-only search; an even smaller failure may still exist. Supported curated list and string questions only.": "最多執行 10 個案例，只透過刪減輸入搜尋，還可能存在更小的反例。目前支援部分精選串列與字串題目。",
  "Could not reduce this failing input.": "無法縮減這個失敗輸入。",
