  "Revisit question": "重練這題",
  "You are caught up. Try a new question, or revisit one from Coming up.": "目前沒有到期的複習。可以練新題，或從「接下來的安排」提前複習。",
  "Your next reviews will appear after a recorded submission.": "完成並儲存一次正式提交後，這裡就會安排複習。",
  "Review intervals: 1, 3, 7, 14 and 30 days. Same-day passing submissions do not advance the interval. A failed submission resets it. This is a practice reminder, not a mastery score.": "複習間隔為 1、3、7、14、30 天。同一天重複通過不會增加間隔；提交未通過時會重新計算。這是練習提醒，不代表已精通。",
  "Explain it like an interview.": "像面試時一樣，把解法講清楚。",
