  "Send explanation · AI credits": "送出講解 · 使用 AI 額度",
  "Finish and review · No AI": "結束並查看回饋 · 不使用 AI",
  "Sending uses your explanation, saved solution, public examples and test counts. Hidden test inputs are not sent. Your recording is never submitted automatically.": "送出時會使用你的講解、已儲存的程式、公開範例及測試數量，不會傳送隱藏測試輸入。錄音不會自動提交。",
  "Practice complete. Review the feedback, then try explaining the idea once more in your own words.": "練習完成。看完回饋後，再試著用自己的話重新講解一次。",
  "Allow recording. Browser transcription may send audio to its speech service.": "同意錄音。瀏覽器的語音轉文字功能可能將音訊傳送至其語音服務。",
  "Record explanation": "錄下你的講解",
