  "Recordings stay in this page and are cleared when you leave. Only the reviewed text is sent for AI feedback.": "錄音只保留在本頁，離開後即清除。只有你確認送出的文字會用來取得 AI 回饋。",
  "Oral practice request failed.": "口述練習暫時無法完成，請再試一次。",
