  "No AI · Uses this replay": "不使用 AI · 根據這次實際執行",
  "No suitable state changes were captured. This quiz uses complete integer, boolean and None values in adjacent line events. Explore the trace instead.": "這次沒有適合出題的狀態變化。小測驗只使用相鄰執行紀錄中完整的整數、布林值與 None；你仍可查看原始軌跡。",
