  "The observed value differs. Follow the highlighted line again.": "實際觀察到的值不同，再沿著標示的程式碼推演一次。",
  "Captured before line {0}. This is an observed state, not an AI explanation.": "這個值記錄於第 {0} 行執行前，來自實際執行，而非 AI 推測。",
  "Previous question": "上一題",
  "Next question": "下一題",
  "Practice complete. Explain why each value changed before trying another input.": "練習完成。換下一個輸入之前，試著說明每個變數為什麼改變。",
  "This practice uses a replay you may already have explored. It is not an independent skill assessment and does not change test results. Only captured steps are used; a truncated trace may omit later behavior.": "這項練習使用你可能已看過的軌跡，不代表獨立能力評估，也不會修改測試結果。出題僅使用已記錄的步驟，截斷的軌跡可能省略後續行為。",
  "Think. Test. Reflect.": "先想原因，再用實驗驗證。",
  "Debug hypothesis journal · No AI": "除錯假設筆記 · 不使用 AI",
  "Write down what you suspect before editing. Compare the experiment with your prediction, then keep what you learned.": "改程式之前，先寫下你懷疑的原因。比較實驗結果與原本預測，再留下你的發現。",
  "Reload journal": "重新載入筆記",
  "Loading debug journal…": "正在載入除錯筆記…",
  "What do you suspect?": "你懷疑原因是什麼？",
