  "What change or check will you try?": "你打算改什麼，或怎麼檢查？",
  "Example: change only the loop condition, then rerun the same tests.": "例如：只調整迴圈條件，再執行同一組測試。",
  "What do you expect to observe?": "你預期會觀察到什麼？",
  "Example: the boundary case passes and the other cases stay passing.": "例如：邊界案例通過，其他原本通過的案例也維持通過。",
  "Save hypothesis before editing": "先儲存假設，再修改程式",
  "Hypothesis saved. Make your change, then run tests.": "假設已儲存。現在可以修改程式，再執行測試。",
  "Observed result attached. Decide what it tells you.": "已附上實際結果，想想它說明了什麼。",
  "Your debugging reflection is saved.": "你的除錯心得已儲存。",
  "My hypothesis": "我的假設",
  "My experiment": "我的實驗方式",
  "My prediction": "我的預測",
  "Before the experiment": "實驗之前",
  "Observed after the experiment": "實驗後的觀察",
  "Replace with latest test result": "改用最新測試結果",
  "Attach latest test result": "附上最新測試結果",
  "Edit your solution, run tests, then attach the result. Attaching does not execute code.": "修改程式並執行測試後，再附上結果。附上紀錄本身不會重新執行程式。",
  "Same contract and test set. Compare the counts, then inspect the individual cases.": "需求與測試集相同。先比較通過數量，再查看個別案例。",
  "The contract or test set differs. These counts cannot establish a repair; keep this conclusion uncertain.": "需求或測試集不同，不能只靠通過數量判定修復，這次結論請保留為「還不確定」。",
  "View the recorded code": "查看當時的程式",
  "My conclusion": "我的結論",
  "My evidence supports this idea": "我的證據支持這個想法",
  "My evidence does not support this idea": "我的證據不支持這個想法",
  "Still uncertain": "還不確定",
  "What did the experiment teach you?": "這次實驗讓你學到了什麼？",
  "Explain what changed, what did not, and what you would check next.": "說明哪些地方改變、哪些沒有改變，以及接下來還想檢查什麼。",
  "Save reflection and close hypothesis": "儲存心得，結束這次假設",
  "{0} saved debugging reflections": "已儲存 {0} 則除錯心得",
  "Conclusions are your interpretation, not a proof of the cause. Passing tests after a change does not establish correctness for every input.": "結論是你對證據的解讀，不代表已證明錯誤原因。修改後測試通過，也不代表對所有輸入都正確。",
  "Could not update the debug journal.": "目前無法更新除錯筆記。",
  "Debug journal was not found.": "找不到除錯筆記。",
  "Choose a debug journal action and revision.": "筆記狀態無效，請重新載入。",
  "This debug journal is being updated.": "這份除錯筆記正在更新，請稍候。",
  "This debug journal changed elsewhere. Reload before saving.": "這份筆記已在其他地方更新，請重新載入後再儲存。",
  "Describe a hypothesis, experiment and prediction in up to 1,500 characters each.": "請填寫假設、實驗方式及預測，每欄最多 1,500 字元。",
  "Conclude the open hypothesis before starting another.": "請先結束目前的假設，再開始下一個。",
  "This question already has 30 saved hypotheses.": "這題已儲存 30 則假設筆記。",
  "Start with a saved failing test result.": "請先執行測試，從已儲存的失敗結果開始。",
  "This hypothesis is no longer open.": "這則假設已結束，請重新載入筆記。",
  "Run a new experiment before attaching its result.": "請先完成新的實驗並執行測試，再附上結果。",
  "Choose your conclusion and explain it in up to 1,500 characters.": "請選擇結論，並用 1,500 字元以內說明。",
  "Without comparable test evidence, keep the conclusion inconclusive.": "目前沒有可直接比較的測試證據，請將結論保留為「還不確定」。",
  "Choose a saved test result for this solution.": "請選擇這份程式已儲存的測試結果。",
  "The saved result no longer matches this code or test contract. Run the tests again.": "已儲存的結果與目前程式或需求不符，請重新執行測試。",
  "Start the same question again": "從頭重練同一題",
  "A fresh attempt at a familiar problem.": "熟悉的題目，重新靠自己寫一次。",
  "Try it again from the beginning.": "不接著舊答案，從頭再試一次。",
  "This attempt starts from the original code. Earlier answers, hints and test results stay in the previous attempt.": "這次從原始起始程式開始，先前的解答、提示與測試紀錄都保留在上一份練習。",
  "Keep this attempt and open a separate one with the same question, tests and original starter code.": "保留目前作答，另開一份相同題目與測試的練習，從原始起始程式重新開始。",
  "Start fresh attempt · No AI": "從頭重練 · 不使用 AI",
  "Back to previous attempt": "回到上一份作答",
  "Debug and optimization practice keep the original flawed or slow starter. This is a previously seen question, not an independent assessment. Starting alone does not count toward your practice goal.": "除錯與效能練習會保留原本有問題或較慢的起始程式。這是重練看過的題目，不代表獨立能力評估；只開啟練習不會計入每日目標。",
  "Preparing a fresh attempt…": "正在準備新的重練作答…",
  "Fresh attempt ready. Your previous draft is preserved.": "已準備好從頭重練，上一份草稿仍然保留。",
  "Another fresh attempt is being prepared.": "正在準備另一份重練作答，請稍候。",
  "This saved question has no usable starter code.": "這份題目沒有可用的起始程式。",
  "Fresh attempt": "從頭重練",
