  "No more suggestions are available right now. You can choose a topic from the practice desk.": "目前沒有其他適合的建議，可以回練習桌自行選擇題型。",
  "Suggestions update as you submit work or change your daily goal. New questions use prepared Invarith exercises. This is a practice plan, not a skill rating.": "提交作答或調整每日目標後，安排會跟著更新。新題使用 Invarith 現成題庫，這是練習建議，不代表能力評分。",
