  "Searching saved practice…": "正在搜尋已儲存練習…",
  "{0} matching saved attempts": "找到 {0} 份符合條件的作答",
  "Retry search": "重試搜尋",
  "Untitled practice": "未命名的練習",
  "Not estimated": "尚未估計難度",
  "Date unavailable": "日期未記錄",
  "Practice": "練習",
  "No saved attempts match. Try clearing a filter, or start a question from the practice desk.": "目前沒有符合條件的作答。可以清除篩選，或到練習桌開始一題。",
  "Saved practice pages": "已儲存練習分頁",
  "Previous page": "上一頁",
  "Next page": "下一頁",
  "Page {0} of {1}": "第 {0} 頁，共 {1} 頁",
  "Each row is a saved attempt; retries can share a question. Status uses saved hidden-test submissions, not public-example runs, and does not prove general correctness. Search does not inspect code, hints or private test inputs.": "每列是一份已儲存作答，同一題的重練會分開列出。狀態依據正式隱藏測試提交，不以公開範例判定，也不代表對所有輸入都正確。搜尋不會查看程式、提示或隱藏測試輸入。",
  "Finish the current operation, then open this saved attempt.": "請先完成目前的操作，再開啟這份作答。",
  "Choose supported library filters and a search of up to 120 characters.": "請使用支援的題庫篩選條件，搜尋文字最多 120 字元。",
  "Could not search saved practice.": "暫時無法搜尋已儲存練習。",
  "Could not search saved practice. Check the local app and try again.": "無法搜尋已儲存練習，請確認本機程式仍在執行後重試。",
  "What changed on your retry?": "這次重練，哪些地方改變了？",
  "Compare your latest saved hidden-test submission with the version captured when this retry began.": "比較這次最近的正式提交，與開始重練時保留下來的上一版作答。",
  "Saved evidence · No AI": "已儲存證據 · 不使用 AI",
  "Submit this retry to hidden tests first. The previous code stays out of this comparison until then.": "先將這次重練提交至隱藏測試，之後才會在這裡顯示上一版程式。",
  "Comparing saved attempts…": "正在比較已儲存作答…",
  "Reload comparison": "重新載入比較",
  "No submitted version was captured when this retry began. After submitting this attempt, start a new retry to record a comparison baseline.": "這次重練開始時，沒有保留下可比較的正式提交。完成這份作答後，再開一次重練，就能記錄比較基準。",
  "The saved evidence is incomplete. Submit this retry again before comparing.": "已儲存的證據不完整，請重新提交這次重練後再比較。",
  "Previous attempt at retry start": "開始重練時的上一版",
  "This retry’s saved submission": "這次重練的正式提交",
  "Recorded assistant requests: {0}": "紀錄中的助理提問次數：{0}",
  "Your editor differs from this saved submission. The comparison does not grade your current draft.": "目前編輯器的程式與已提交版本不同，這份比較不代表目前草稿的測試結果。",
  "Contracts, test expectations or saved evidence differ. Code can be compared, but fixes and regressions cannot be counted.": "需求、測試預期或已儲存證據不一致。仍可看程式碼差異，但不能計算修復或退步的案例數。",
  "Code changes · Previous attempt → retry": "程式碼變更 · 上一版 → 這次重練",
  "Previous version captured at {0}. Later edits to that attempt do not change this baseline.": "上一版儲存於 {0}。之後修改舊作答，也不會改變這份比較基準。",
  "This is a previously seen question. Assistant counts reflect recorded in-app requests only; other help and lesson viewing are not measured. Better test results or fewer requests do not prove independent skill improvement.": "這是已看過的題目。助理次數只計算站內已記錄的提問，不包含其他求助或教學觀看情況。測試變好或提問變少，都不能單獨證明獨立解題能力提升。",
  "Could not compare retry attempts.": "目前無法比較重練紀錄，請稍後重試。",
  "This saved attempt is not a retry.": "這份作答不是從頭重練的紀錄。",
  "Your week in practice.": "回頭看看，這七天練了什麼。",
  "See what you practiced and which saved results deserve another look.": "整理練過的題型，也找出值得再回看的作答。",
  "Copy seven-day summary": "複製七天摘要",
