  "{0} vs previous 7 days": "較前七天 {0}",
  "Latest results are taken separately for each question within the selected date range.": "每一題的結果，採用所選期間內最近一次已儲存提交。",
  "Questions with a non-passing latest result: {0}": "這段期間有 {0} 題的最近提交仍有案例未通過。",
