  "Open a saved question": "開啟相關舊題",
  "No recorded submissions in this period. Your next practice can be a small one.": "這段期間還沒有提交紀錄。下一次練習，從一個小題目開始也很好。",
  "Show all {0} topics": "顯示全部 {0} 種題型",
