  "Seven-day practice review": "七天學習回顧",
  "Questions with a passing latest result": "最近結果通過的題目數",
  "Questions: {0}; latest passing: {1}; submissions: {2}": "題目：{0}；最近結果通過：{1}；提交：{2}",
  "Saved test outcomes describe tested inputs, not mastery.": "已儲存的測試結果只描述測過的輸入，不代表已精通。",
  "Seven-day summary copied.": "已複製七天學習摘要。",
  "Your browser could not copy automatically. Select the summary below to copy it.": "瀏覽器無法自動複製，請選取下方摘要後手動複製。",
  "This review uses retained saved submissions. Retries of the same question count once in question totals, but each recorded submission counts as practice activity. The last-7-days view includes today so far; activity changes are not skill scores.": "回顧以目前保留的提交紀錄統計。同一題重練多次，題目數只算一次，但各次提交會算入練習量。「最近七天」包含今天目前的紀錄；練習量變化不代表能力分數。",
